#!/usr/bin/env bash
# CI diff of WASM exports against cargo public-api output to detect unintended
# WASM surface additions (CLAIM-49.3, PV-17.1).
#
# The committed baseline is tirbase-core/wasm-public-api.txt (generated by
# cargo +nightly public-api for tirbase-core's public Rust surface). When the
# wasm32 target and wasm-pack are available, we also build the wasm surface and
# record exported symbol names for visibility in CI artifacts/logs.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

MANIFEST="tirbase-core/wasm-public-api.txt"
if [[ ! -f "$MANIFEST" ]]; then
  echo "ERROR: missing WASM/public API baseline manifest: $MANIFEST"
  exit 1
fi

TMP="$(mktemp)"
ERR="$(mktemp)"
cleanup() { rm -f "$TMP" "$ERR"; }
trap cleanup EXIT

# Diff the public API surface (cargo public-api is the authoritative diff gate).
if command -v cargo >/dev/null 2>&1 && cargo +nightly public-api --help >/dev/null 2>&1; then
  cargo +nightly public-api -p tirbase-core >"$TMP" 2>"$ERR" || {
    echo "ERROR: failed to generate tirbase-core public API"
    cat "$ERR"
    exit 1
  }
  if ! diff -u "$MANIFEST" "$TMP"; then
    echo "ERROR: tirbase-core public/WASM API surface differs from $MANIFEST"
    echo "Unintended surface additions are rejected. If intentional, update the manifest deliberately."
    exit 1
  fi
  echo "OK: tirbase-core public API matches $MANIFEST"
else
  echo "WARN: cargo +nightly public-api unavailable; falling back to manifest presence check"
  grep -q "pub " "$MANIFEST" || { echo "ERROR: baseline manifest appears empty"; exit 1; }
fi

# Best-effort wasm export inventory when wasm-pack target is present.
if command -v wasm-pack >/dev/null 2>&1 && rustup target list --installed 2>/dev/null | grep -q wasm32-unknown-unknown; then
  OUT="$(mktemp -d)"
  wasm-pack build tirbase-core --no-default-features --features wasm --target web --out-dir "$OUT/pkg" --dev >/tmp/wasm-pack-surface.log 2>&1 || {
    echo "WARN: wasm-pack build unavailable for export inventory; cargo-public-api diff remains authoritative"
    rm -rf "$OUT"
    exit 0
  }
  if command -v wasm-objdump >/dev/null 2>&1 && ls "$OUT"/pkg/*.wasm >/dev/null 2>&1; then
    wasm-objdump -x "$OUT"/pkg/*.wasm | grep -E 'export|func\[' | sort > "$OUT/wasm-exports.txt" || true
    echo "WASM exports inventory: $(wc -l < "$OUT/wasm-exports.txt") lines"
  fi
  rm -rf "$OUT"
fi

echo "OK: WASM export/public API diff check passed."
